import {HStack,VStack,Text,Link,Image,Spacer} from '@expo/ui/swift-ui';
import {font,foregroundStyle,widgetURL,containerBackground,accessibilityLabel,lineLimit,frame,background,shapes,privacySensitive,minimumScaleFactor,resizable,clipShape,accessibilityHidden,monospacedDigit} from '@expo/ui/swift-ui/modifiers';
import {createWidget,type WidgetEnvironment} from 'expo-widgets';
import {widgetPresentation,type WidgetPresentation} from './widget-copy';
import type {AttendanceWidgetSnapshot} from './widget-snapshot';

const InWidget=(p:WidgetPresentation,e:WidgetEnvironment)=>{
 'widget';
 const dark=e.colorScheme==='dark',ink=dark?'#F5F3EF':'#111111',muted=dark?'#BCBAB6':'#555555';
 if(e.widgetFamily==='accessoryCircular')return <VStack modifiers={[widgetURL('aihr://clock?action=in'),accessibilityLabel(p.clockIn)]}><Image systemName="arrow.down.right.circle"/></VStack>;
 return <VStack alignment="leading" spacing={2} modifiers={[widgetURL('aihr://clock?action=in'),frame({maxWidth:999,maxHeight:999,alignment:'leading'}),containerBackground(dark?'#101010':'#FFFFFF','widget')]}>
  <HStack spacing={6}><Image uiImage={"data:image/png;base64,"} modifiers={[resizable(),frame({width:20,height:20}),clipShape('roundedRectangle',6),accessibilityHidden(true)]}/><Text modifiers={[font({size:12,weight:'semibold'}),foregroundStyle(ink)]}>OneHR+</Text></HStack>
  <Text modifiers={[font({size:11}),foregroundStyle(muted),lineLimit(1),minimumScaleFactor(1),privacySensitive()]}>{p.status} · {p.clockIn}</Text>
  <Text modifiers={[font({size:26,weight:'regular'}),monospacedDigit(),lineLimit(1),minimumScaleFactor(.75),foregroundStyle(ink),privacySensitive()]}>{p.inTime}</Text>
  <HStack spacing={6} modifiers={[frame({maxWidth:999,minHeight:32}),background('#D92D20',shapes.roundedRectangle({cornerRadius:12}))]}><Image systemName="arrow.right.to.line" size={14} color="#FFFFFF"/><Text modifiers={[font({size:13,weight:'semibold'}),foregroundStyle('#FFFFFF'),lineLimit(1),minimumScaleFactor(.85)]}>{p.clockIn}</Text></HStack>
  <VStack alignment="leading" spacing={0} modifiers={[frame({minHeight:26,alignment:'leading'})]}><Text modifiers={[font({size:11}),foregroundStyle(muted),lineLimit(1),minimumScaleFactor(1),privacySensitive()]}>{p.updated.split(' · ')[0]}</Text><Text modifiers={[font({size:11}),foregroundStyle(muted),lineLimit(1),minimumScaleFactor(1),privacySensitive()]}>{p.updated.split(' · ')[1]??''}</Text></VStack>
 </VStack>;
};
const OutWidget=(p:WidgetPresentation,e:WidgetEnvironment)=>{
 'widget';
 const dark=e.colorScheme==='dark',ink=dark?'#F5F3EF':'#111111',muted=dark?'#BCBAB6':'#555555';
 if(e.widgetFamily==='accessoryCircular')return <VStack modifiers={[widgetURL('aihr://clock?action=out'),accessibilityLabel(p.clockOut)]}><Image systemName="arrow.up.right.circle"/></VStack>;
 return <VStack alignment="leading" spacing={2} modifiers={[widgetURL('aihr://clock?action=out'),frame({maxWidth:999,maxHeight:999,alignment:'leading'}),containerBackground(dark?'#101010':'#FFFFFF','widget')]}>
  <HStack spacing={6}><Image uiImage={"data:image/png;base64,"} modifiers={[resizable(),frame({width:20,height:20}),clipShape('roundedRectangle',6),accessibilityHidden(true)]}/><Text modifiers={[font({size:12,weight:'semibold'}),foregroundStyle(ink)]}>OneHR+</Text></HStack>
  <Text modifiers={[font({size:11}),foregroundStyle(muted),lineLimit(1),minimumScaleFactor(1),privacySensitive()]}>{p.status} · {p.clockOut}</Text>
  <Text modifiers={[font({size:26,weight:'regular'}),monospacedDigit(),lineLimit(1),minimumScaleFactor(.75),foregroundStyle(ink),privacySensitive()]}>{p.outTime}</Text>
  <HStack spacing={6} modifiers={[frame({maxWidth:999,minHeight:32}),background('#D92D20',shapes.roundedRectangle({cornerRadius:12}))]}><Image systemName="arrow.up.right" size={14} color="#FFFFFF"/><Text modifiers={[font({size:13,weight:'semibold'}),foregroundStyle('#FFFFFF'),lineLimit(1),minimumScaleFactor(.85)]}>{p.clockOut}</Text></HStack>
  <VStack alignment="leading" spacing={0} modifiers={[frame({minHeight:26,alignment:'leading'})]}><Text modifiers={[font({size:11}),foregroundStyle(muted),lineLimit(1),minimumScaleFactor(1),privacySensitive()]}>{p.updated.split(' · ')[0]}</Text><Text modifiers={[font({size:11}),foregroundStyle(muted),lineLimit(1),minimumScaleFactor(1),privacySensitive()]}>{p.updated.split(' · ')[1]??''}</Text></VStack>
 </VStack>;
};
const ActionsWidget=(p:WidgetPresentation,e:WidgetEnvironment)=>{
 'widget';
 const dark=e.colorScheme==='dark',ink=dark?'#F5F3EF':'#111111',muted=dark?'#BCBAB6':'#555555';
 return <VStack alignment="leading" spacing={2} modifiers={[frame({maxWidth:999,maxHeight:999,alignment:'leading'}),containerBackground(dark?'#101010':'#FFFFFF','widget')]}>
  <HStack spacing={8}><Image uiImage={"data:image/png;base64,"} modifiers={[resizable(),frame({width:22,height:22}),clipShape('roundedRectangle',6),accessibilityHidden(true)]}/><Text modifiers={[font({size:13,weight:'semibold'}),foregroundStyle(ink)]}>OneHR+</Text><Spacer/><Text modifiers={[font({size:11}),foregroundStyle(muted),lineLimit(1),minimumScaleFactor(1),privacySensitive()]}>{p.status}</Text></HStack>
  <HStack spacing={20}>
   <VStack alignment="leading" spacing={0} modifiers={[frame({maxWidth:999,alignment:'leading'})]}><Text modifiers={[font({size:11}),foregroundStyle(muted)]}>{p.clockIn}</Text><Text modifiers={[font({size:28,weight:'regular'}),monospacedDigit(),lineLimit(1),minimumScaleFactor(.75),foregroundStyle(ink),privacySensitive()]}>{p.inTime}</Text></VStack>
   <VStack alignment="leading" spacing={0} modifiers={[frame({maxWidth:999,alignment:'leading'})]}><Text modifiers={[font({size:11}),foregroundStyle(muted)]}>{p.clockOut}</Text><Text modifiers={[font({size:28,weight:'regular'}),monospacedDigit(),lineLimit(1),minimumScaleFactor(.75),foregroundStyle(ink),privacySensitive()]}>{p.outTime}</Text></VStack>
  </HStack>
  <HStack spacing={10}>
   <Link destination="aihr://clock?action=in" modifiers={[frame({maxWidth:999,minHeight:44}),background(p.active?(dark?'#292929':'#EEEEEE'):'#D92D20',shapes.roundedRectangle({cornerRadius:12})),accessibilityLabel(p.clockIn)]}><HStack spacing={6}><Image systemName="arrow.right.to.line" size={15} color={p.active?ink:'#FFFFFF'}/><Text modifiers={[font({size:14,weight:'semibold'}),foregroundStyle(p.active?ink:'#FFFFFF'),lineLimit(1),minimumScaleFactor(.8)]}>{p.clockIn}</Text></HStack></Link>
   <Link destination="aihr://clock?action=out" modifiers={[frame({maxWidth:999,minHeight:44}),background(p.active?'#D92D20':(dark?'#292929':'#EEEEEE'),shapes.roundedRectangle({cornerRadius:12})),accessibilityLabel(p.clockOut)]}><HStack spacing={6}><Image systemName="arrow.up.right" size={15} color={p.active?'#FFFFFF':ink}/><Text modifiers={[font({size:14,weight:'semibold'}),foregroundStyle(p.active?'#FFFFFF':ink),lineLimit(1),minimumScaleFactor(.8)]}>{p.clockOut}</Text></HStack></Link>
  </HStack>
  <Text modifiers={[font({size:11}),foregroundStyle(muted),lineLimit(1),minimumScaleFactor(1),privacySensitive()]}>{p.updated}</Text>
 </VStack>;
};
const clockIn=createWidget('OneHRClockIn',InWidget),clockOut=createWidget('OneHRClockOut',OutWidget),actions=createWidget('OneHRAttendance',ActionsWidget);
export function updateAttendanceWidgets(snapshot:AttendanceWidgetSnapshot|null):void{
 try{
  const props=widgetPresentation(snapshot),empty=widgetPresentation(null);
  for(const widget of [clockIn,clockOut,actions]){
   if(snapshot)widget.updateTimeline([{date:new Date(),props},{date:new Date(snapshot.expiresAt),props:empty}]);
   else widget.updateSnapshot(empty);
  }
 }catch{/* A widget failure cannot block authentication or attendance. */}
}
export function initializeAttendanceWidgets():void{updateAttendanceWidgets(null);}
